use serde_json::{Value, Map};
use std::collections::BTreeMap;

pub fn solve(input: Value) -> Value {
    let mut map = BTreeMap::new();
    if let Value::Array(arr) = input {
        for item in arr {
            if let Value::Array(row) = item {
                if let (Value::Number(num_key), Value::Number(num_val)) = (&row[0], &row[1]) {
                    let key = num_key.as_i64().unwrap();
                    let val = num_val.as_i64().unwrap();
                    *map.entry(key).or_insert(0) += val;
                }
            }
        }
    }
    let mut result = Vec::new();
    for (key, val) in map {
        result.push(Value::Array(vec![
            Value::Number(key.into()),
            Value::Number(val.into()),
        ]));
    }
    Value::Array(result)
}
